lee: Python snippet (short):

```python
import time, requests, random

def retry_get(url, attempts=3, base=0.1):
    for i in range(attempts):
        try:
            return requests.get(url, stream=True, timeout=10)
        except requests.RequestException:
            if i == attempts - 1:
                raise
            sleep = base * (2 ** i) + random.uniform(0, base)
            time.sleep(sleep)

def stream_with_resume(url, cursor=None):
    params = {}
    if cursor: params['cursor'] = cursor
    resp = retry_get(url if not params else f\"{url}?cursor={cursor}\")
    for line in resp.iter_lines(decode_unicode=True):
        if not line: continue
        if line.startswith('CURSOR:'):
            cursor = line.split(':',1)[1]
        else:
            yield line
```

